//! Rectangular Micro QR (rMQR, ISO/IEC 23941) tests.
//!
//! Two kinds of validation:
//!  1. **External reference vectors** — full module bitmaps generated by the
//!     independent `rmqrcode` library, including single- and multi-block sizes, both
//!     EC levels, and interior-alignment sizes. Our encoder must reproduce them
//!     bit-for-bit.
//!  2. **Round-trip identity** across all 32 sizes and both EC levels.
#![cfg(all(feature = "decode", feature = "encode", feature = "rmqr"))]

use anyd::codes::rmqr::{RmqrDecoder, RmqrEcLevel, RmqrEncoder, RmqrMeta, RmqrSize};
use anyd::output::{BitMatrix, Encoding};
use anyd::segment::Segment;
use anyd::symbol::{Symbol, SymbolMeta};
use anyd::symbology::Symbology;
use anyd::traits::{Decode, Encode};

fn meta(width: usize, height: usize, ec: RmqrEcLevel) -> RmqrMeta {
    RmqrMeta {
        size: RmqrSize::from_dimensions(width, height).unwrap(),
        ec_level: ec,
    }
}

fn assert_matrix(enc: &Encoding, w: usize, h: usize, flat: &str) {
    let Encoding::Matrix(m) = enc else {
        panic!("expected a matrix encoding");
    };
    assert_eq!((m.width(), m.height()), (w, h));
    let bytes = flat.as_bytes();
    assert_eq!(bytes.len(), w * h, "reference length mismatch");
    for y in 0..h {
        for x in 0..w {
            let want = bytes[y * w + x] == b'1';
            assert_eq!(m.get(x, y), want, "module ({x},{y}) differs from reference");
        }
    }
}

/// Encode a byte segment against a reference bitmap, then assert round-trip identity.
fn check(content: &[u8], w: usize, h: usize, ec: RmqrEcLevel, flat: &str) {
    let m = meta(w, h, ec);
    let sym = Symbol::new(
        Symbology::RectMicroQrCode,
        vec![Segment::byte(content.to_vec())],
        SymbolMeta::Rmqr(m),
    );
    let enc = RmqrEncoder::new().encode(&sym).unwrap();
    assert_matrix(&enc, w, h, flat);

    let decoded = RmqrDecoder::new().decode(&enc).unwrap();
    assert_eq!(
        decoded.segments, sym.segments,
        "segments differ after decode"
    );
    assert_eq!(decoded.meta, sym.meta, "meta differs after decode");
    assert_eq!(
        RmqrEncoder::new().encode(&decoded).unwrap(),
        enc,
        "re-encode differs"
    );
}

#[test]
fn r7x43_m() {
    check(
        b"HELLO",
        43,
        7,
        RmqrEcLevel::M,
        "",
    );
}

#[test]
fn r7x43_h() {
    check(
        b"Hi",
        43,
        7,
        RmqrEcLevel::H,
        "",
    );
}

#[test]
fn r11x27_m() {
    check(
        b"test",
        27,
        11,
        RmqrEcLevel::M,
        "111111101010101010101010111100000101110110001000011001101110100111010001001101001101110100010001000111111010101110100001011110011110001100000100110100100001110110111111101100100111100111111000000001100101011001010001111110000001101000010110101101110000110110100101010001111010101010101010101011111",
    );
}

#[test]
fn r13x27_h() {
    check(
        b"AB",
        27,
        13,
        RmqrEcLevel::H,
        "",
    );
}

// Asymmetric multi-block sizes: the reference `rmqrcode` library has a codeword-
// interleaving bug (it drops the longest block's tail data codeword), so its bitmaps
// for these sizes are non-conformant and cannot be used as reference vectors. We
// instead exercise our ISO-standard interleaving (identical to the validated QR
// module) via round-trip identity, which spans multiple blocks with these payloads.
#[test]
fn r9x77_h_two_blocks_roundtrip() {
    roundtrip_size(
        RmqrSize::from_dimensions(77, 9).unwrap(),
        RmqrEcLevel::H,
        Segment::byte(b"block12 payload".to_vec()),
    );
}

#[test]
fn r11x99_m_two_blocks_roundtrip() {
    roundtrip_size(
        RmqrSize::from_dimensions(99, 11).unwrap(),
        RmqrEcLevel::M,
        Segment::byte(b"R11x99 two data blocks payload here".to_vec()),
    );
}

#[test]
fn r13x139_m_three_blocks_roundtrip() {
    roundtrip_size(
        RmqrSize::from_dimensions(139, 13).unwrap(),
        RmqrEcLevel::M,
        Segment::byte(b"R13x139 three block interleave test payload content".to_vec()),
    );
}

#[test]
fn r17x139_m_four_blocks() {
    let content = vec![b'X'; 140];
    check(
        &content,
        139,
        17,
        RmqrEcLevel::M,
        "",
    );
}

// --- Round-trip across every size and level via explicit metadata ---

fn roundtrip_size(size: RmqrSize, ec: RmqrEcLevel, seg: Segment) {
    let sym = Symbol::new(
        Symbology::RectMicroQrCode,
        vec![seg],
        SymbolMeta::Rmqr(RmqrMeta { size, ec_level: ec }),
    );
    let enc = RmqrEncoder::new().encode(&sym).unwrap();
    let decoded = RmqrDecoder::new().decode(&enc).unwrap();
    assert_eq!(decoded.segments, sym.segments, "{} segments", size.name());
    assert_eq!(decoded.meta, sym.meta, "{} meta", size.name());
    assert_eq!(
        RmqrEncoder::new().encode(&decoded).unwrap(),
        enc,
        "{} re-encode",
        size.name()
    );
}

#[test]
fn every_size_and_level_roundtrips() {
    for size in RmqrSize::all() {
        for ec in [RmqrEcLevel::M, RmqrEcLevel::H] {
            // A tiny numeric payload fits even the smallest capacity (R7x43-H, 24 bits).
            roundtrip_size(size, ec, Segment::numeric(b"42".to_vec()));
        }
    }
}

#[test]
fn builder_selects_and_roundtrips() {
    let enc = RmqrEncoder::new();
    for (content, level) in [
        ("anydcode rMQR", RmqrEcLevel::M),
        ("HELLO WORLD 12345", RmqrEcLevel::H),
        ("https://example.com/rmqr?q=1", RmqrEcLevel::M),
    ] {
        let sym = enc.build_text(content, level).unwrap();
        let e = enc.encode(&sym).unwrap();
        let d = RmqrDecoder::new().decode(&e).unwrap();
        assert_eq!(d.text().as_deref(), Some(content));
        assert_eq!(enc.encode(&d).unwrap(), e);
    }
}

#[test]
fn mixed_segments_preserve_boundaries() {
    let size = RmqrSize::from_dimensions(99, 11).unwrap();
    let segs = vec![
        Segment::numeric(b"12345".to_vec()),
        Segment::alphanumeric(b"ABC".to_vec()),
        Segment::byte(b"xyz!".to_vec()),
    ];
    let sym = Symbol::new(
        Symbology::RectMicroQrCode,
        segs.clone(),
        SymbolMeta::Rmqr(RmqrMeta {
            size,
            ec_level: RmqrEcLevel::M,
        }),
    );
    let e = RmqrEncoder::new().encode(&sym).unwrap();
    let d = RmqrDecoder::new().decode(&e).unwrap();
    assert_eq!(d.segments, segs);
}

#[test]
fn survives_correctable_error() {
    let enc = RmqrEncoder::new();
    let sym = enc.build_text("RESILIENT rMQR", RmqrEcLevel::H).unwrap();
    let Encoding::Matrix(mut m) = enc.encode(&sym).unwrap() else {
        panic!("expected matrix");
    };
    // Flip a couple of interior data modules.
    for (x, y) in [(15usize, 3usize), (20, 4)] {
        if x < m.width() && y < m.height() {
            let v = m.get(x, y);
            m.set(x, y, !v);
        }
    }
    let d = RmqrDecoder::new().decode(&Encoding::Matrix(m)).unwrap();
    assert_eq!(d.text().as_deref(), Some("RESILIENT rMQR"));
}

#[test]
fn wrong_size_matrix_is_undecodable() {
    let m = BitMatrix::new(40, 8, 2);
    assert!(RmqrDecoder::new().decode(&Encoding::Matrix(m)).is_err());
}

#[test]
fn size_strategy_picks_shape() {
    use anyd::codes::rmqr::{RmqrEcLevel, RmqrEncoder, SizeStrategy};
    use anyd::output::Encoding;
    use anyd::traits::Encode;
    let e = RmqrEncoder::new();
    let dims = |s| {
        let sym = e
            .build_text_with("HELLO WORLD 12345", RmqrEcLevel::M, s)
            .unwrap();
        match e.encode(&sym).unwrap() {
            Encoding::Matrix(m) => (m.width(), m.height()),
            _ => unreachable!(),
        }
    };
    let (_, bh) = dims(SizeStrategy::Balanced);
    let (_, minh) = dims(SizeStrategy::MinHeight);
    let (_, maxh) = dims(SizeStrategy::MaxHeight);
    // min-height must be the shortest, max-height the tallest, all valid rMQR heights.
    assert!(minh <= bh && bh <= maxh);
    assert!(minh < maxh, "strategies should differ ({minh} vs {maxh})");
    for h in [minh, bh, maxh] {
        assert!([7, 9, 11, 13, 15, 17].contains(&h));
    }
}

// --- Automatic mode selection in build_text ---

#[test]
fn build_text_picks_dense_modes() {
    let enc = RmqrEncoder::new();
    let sym = enc
        .build_text("HELLO WORLD 123456789", RmqrEcLevel::M)
        .unwrap();
    assert_eq!(
        sym.segments,
        vec![
            Segment::alphanumeric(b"HELLO WORLD ".to_vec()),
            Segment::numeric(b"123456789".to_vec()),
        ]
    );
    let encoding = enc.encode(&sym).unwrap();
    let decoded = RmqrDecoder::new().decode(&encoding).unwrap();
    assert_eq!(decoded.segments, sym.segments);
    assert_eq!(RmqrEncoder::new().encode(&decoded).unwrap(), encoding);
}

/// The rMQR terminator is the `000` mode indicator, so a zero character count is an
/// ordinary (empty) segment — what `build_text("")` makes — and must survive the
/// round trip together with whatever follows it.
#[test]
fn empty_segments_roundtrip() {
    let enc = RmqrEncoder::new();
    for sym in [
        enc.build_text("", RmqrEcLevel::M).unwrap(),
        enc.build(
            vec![Segment::byte(Vec::new()), Segment::numeric(b"123".to_vec())],
            RmqrEcLevel::H,
        )
        .unwrap(),
    ] {
        let encoding = enc.encode(&sym).unwrap();
        let decoded = RmqrDecoder::new().decode(&encoding).unwrap();
        assert_eq!(decoded, sym);
        assert_eq!(enc.encode(&decoded).unwrap(), encoding);
    }
}

#[test]
fn build_text_utf8_roundtrips() {
    let enc = RmqrEncoder::new();
    let sym = enc.build_text("héllo 12345678", RmqrEcLevel::M).unwrap();
    let flat: Vec<u8> = sym.segments.iter().flat_map(|s| s.data.clone()).collect();
    assert_eq!(flat, "héllo 12345678".as_bytes().to_vec());
    let encoding = enc.encode(&sym).unwrap();
    let decoded = RmqrDecoder::new().decode(&encoding).unwrap();
    assert_eq!(decoded.segments, sym.segments);
}

/// Kanji mode round-trips, and a Shift-JIS trail byte below 0x40 (which would alias
/// another character's 13-bit value) is rejected rather than silently re-mapped.
#[test]
fn kanji_roundtrips_and_rejects_bad_trail_byte() {
    let enc = RmqrEncoder::new();
    let segments = vec![Segment::kanji(vec![0x93, 0x5F, 0xE4, 0xAA])];
    let sym = enc.build(segments, RmqrEcLevel::M).unwrap();
    let encoding = enc.encode(&sym).unwrap();
    let decoded = RmqrDecoder::new().decode(&encoding).unwrap();
    assert_eq!(decoded, sym);
    assert_eq!(enc.encode(&decoded).unwrap(), encoding);

    let bad = enc.build(vec![Segment::kanji(vec![0x82, 0x00])], RmqrEcLevel::M);
    assert!(bad.is_err());
}

/// Parse a flattened `0`/`1` reference bitmap.
fn matrix_from(flat: &str, w: usize, h: usize) -> BitMatrix {
    assert_eq!(flat.len(), w * h);
    let mut m = BitMatrix::new(w, h, 2);
    for (i, b) in flat.bytes().enumerate() {
        m.set(i % w, i / w, b == b'1');
    }
    m
}

/// ECI (mode `111`) against a zint bitmap: `zint -b 145 --eci=26 -d cafe`
/// (R11x27-M). The assignment must be decoded — not mistaken for the terminator,
/// dropping the payload — and re-encode bit-for-bit.
#[test]
fn eci_matches_zint_and_roundtrips() {
    let reference = Encoding::Matrix(matrix_from(
        "111111101010101010101010111100000101110101000100010001101110100111101111110111101101110100010001111001000000101110100001001110111001001100000100110110110001110100111111101111111110000111111000000000000111001101010001110011011101000001010110101101011001111110010101010001111010101010101010101011111",
        27,
        11,
    ));
    let decoded = RmqrDecoder::new().decode(&reference).unwrap();
    assert_eq!(
        decoded.segments,
        [Segment::eci(26), Segment::byte(b"cafe".to_vec())]
    );
    assert_eq!(RmqrEncoder::new().encode(&decoded).unwrap(), reference);

    // Two- and three-byte assignment numbers round-trip too.
    let enc = RmqrEncoder::new();
    for assignment in [0, 127, 128, 16383, 16384, 999_999] {
        let segments = vec![Segment::eci(assignment), Segment::byte(b"x".to_vec())];
        let sym = enc.build(segments, RmqrEcLevel::H).unwrap();
        let encoding = enc.encode(&sym).unwrap();
        assert_eq!(RmqrDecoder::new().decode(&encoding).unwrap(), sym);
    }
}

/// FNC1 modes (`101` / `110`, GS1 and AIM symbols) cannot be represented: the
/// decoder must say so rather than report an empty symbol. Bitmap: `zint -b 145
/// --gs1 -d "[01]12345678901231"` (R13x27-M).
#[test]
fn fnc1_symbol_is_unsupported_not_empty() {
    let reference = Encoding::Matrix(matrix_from(
        "",
        27,
        13,
    ));
    let err = RmqrDecoder::new().decode(&reference).unwrap_err();
    assert!(matches!(err, anyd::Error::Unsupported { .. }), "{err:?}");
}
